-- INSERT renglones 160225, 230501 y 440525 con RNRPFCDS = :DESDE y RNRPORDN en su posicion (re-numerar el orden
--   de los siguientes o usar ordenes intermedios); y revisar las reglas 1.6.02.25 / 1.6.02.30 (hoy -> 160290).

-- BLOQUE 6 — CONTROL DESPUES
-- 6.1 ESPERADO: 1 cabecera, 534 renglones, 33 reglas.
SELECT r.RPRTCDGO, r.RPRTNMBR, r.RPRTALTR, (SELECT COUNT(*) FROM CNT.RNRP n WHERE n.RPRTCDGO = r.RPRTCDGO) renglones,
       (SELECT COUNT(*) FROM CNT.CRRP c WHERE c.RPRTCDGO = r.RPRTCDGO) reglas
  FROM CNT.RPRT r WHERE r.PJRQCDGO = 1236 AND r.RPRTCDES = 'B17';
-- 6.2 Codigos de renglon repetidos. ESPERADO: 0 filas.
SELECT n.RNRPCDRN, COUNT(*) FROM CNT.RNRP n JOIN CNT.RPRT r ON r.RPRTCDGO = n.RPRTCDGO WHERE r.PJRQCDGO = 1236 AND r.RPRTCDES = 'B17' GROUP BY n.RNRPCDRN HAVING COUNT(*) > 1;
-- 6.3 Reglas cuyo destino no es un renglon. ESPERADO: 0 filas.
SELECT c.CRRPCNTA, c.CRRPCDRN FROM CNT.CRRP c JOIN CNT.RPRT r ON r.RPRTCDGO = c.RPRTCDGO WHERE r.PJRQCDGO = 1236 AND r.RPRTCDES = 'B17'
   AND c.CRRPCDRN IS NOT NULL AND NOT EXISTS (SELECT 1 FROM CNT.RNRP n WHERE n.RPRTCDGO = c.RPRTCDGO AND n.RNRPCDRN = c.CRRPCDRN);
-- 6.4 Reglas sobre cuentas que no existen en el plan de la 1236. ESPERADO: 0 filas.
SELECT c.CRRPCNTA FROM CNT.CRRP c JOIN CNT.RPRT r ON r.RPRTCDGO = c.RPRTCDGO WHERE r.PJRQCDGO = 1236 AND r.RPRTCDES = 'B17'
   AND NOT EXISTS (SELECT 1 FROM CNT.PLNN p WHERE p.PJRQCDGO = 1236 AND p.PLNNCNTA = c.CRRPCNTA);

